import pandas as pd
import streamlit as st

from dashboard.utils.database import get_alerts, get_summary

st.set_page_config(
    page_title="Fraud Alerts",
    page_icon="🚨",
    layout="wide",
)

st.title("🚨 Fraud Alert Investigation")
st.caption(
    "Review suspicious transactions generated by the isolated demo pipeline."
)

st.info(
    "Data source: fraud_detection_demo. "
    "These are model-generated alerts, not automatically confirmed fraud cases."
)

# --------------------------------------------------
# REFRESH
# --------------------------------------------------

if st.button("Refresh Alerts"):
    st.cache_data.clear()
    st.rerun()

# --------------------------------------------------
# DEMO DATABASE ONLY
# --------------------------------------------------

try:
    summary = get_summary("demo")
    alerts = get_alerts("demo", limit=100)

except Exception as error:
    st.error(f"Could not read demo alerts: {error}")
    st.stop()

# --------------------------------------------------
# ALERT SUMMARY
# --------------------------------------------------

st.header("Alert Overview")

c1, c2, c3 = st.columns(3)

c1.metric("Total Demo Alerts", summary["alerts"])
c2.metric("High-Risk Transactions", summary["high_risk"])
c3.metric("Demo Transactions", summary["total"])

st.caption(
    "The alert table below displays at most the latest 100 demo alerts."
)

st.divider()

# --------------------------------------------------
# EMPTY STATE
# --------------------------------------------------

if not alerts:
    st.success("No fraud alerts currently exist in the demo environment.")
    st.info(
        "When the demo pipeline processes suspicious transactions, "
        "their alerts will appear here."
    )
    st.stop()

# --------------------------------------------------
# FILTERS
# --------------------------------------------------

st.header("Alert Records")

df = pd.DataFrame(alerts)

if "risk_level" not in df.columns:
    df["risk_level"] = "UNKNOWN"

risk_levels = ["ALL"] + sorted(
    str(value)
    for value in df["risk_level"].dropna().unique()
)

selected_risk = st.selectbox(
    "Filter by risk level",
    options=risk_levels,
)

filtered_df = df.copy()

if selected_risk != "ALL":
    filtered_df = filtered_df[
        filtered_df["risk_level"].astype(str) == selected_risk
    ]

st.caption(f"Showing {len(filtered_df)} matching alerts.")

display_columns = [
    "TransactionID",
    "fraud_probability",
    "risk_level",
    "ground_truth",
    "processed_at",
]

available_columns = [
    column for column in display_columns
    if column in filtered_df.columns
]

st.dataframe(
    filtered_df[available_columns],
    use_container_width=True,
    hide_index=True,
)

# --------------------------------------------------
# ALERT INVESTIGATION
# --------------------------------------------------

st.divider()
st.header("Investigate an Alert")

if filtered_df.empty:
    st.warning("No alerts match the selected risk filter.")
    st.stop()

transaction_ids = filtered_df["TransactionID"].dropna().tolist()

if not transaction_ids:
    st.warning("The returned alerts do not contain transaction IDs.")
    st.stop()

selected_id = st.selectbox(
    "Select a transaction",
    options=transaction_ids,
    format_func=str,
)

selected_alert = next(
    alert for alert in alerts
    if str(alert.get("TransactionID")) == str(selected_id)
)

left, right = st.columns(2)

with left:
    st.subheader("Model Assessment")

    probability = selected_alert.get("fraud_probability")

    if probability is not None:
        st.metric(
            "Fraud Probability",
            f"{float(probability):.2%}",
        )
    else:
        st.metric("Fraud Probability", "Not available")

    st.write(
        "**Risk Level:**",
        selected_alert.get("risk_level", "Not available"),
    )

with right:
    st.subheader("Ground-Truth Label")

    ground_truth = selected_alert.get("ground_truth")

    if ground_truth is None:
        st.info("Ground-truth label is unavailable.")
    elif ground_truth in (1, True):
        st.warning("Dataset label: Fraud")
    elif ground_truth in (0, False):
        st.success("Dataset label: Not fraud")
    else:
        st.info(f"Dataset label: {ground_truth}")

    st.caption(
        "Ground truth is separate from the model's prediction. "
        "An alert alone does not establish confirmed fraud."
    )

# --------------------------------------------------
# BEHAVIOURAL EVIDENCE
# --------------------------------------------------

st.divider()
st.subheader("Behavioural Evidence")

flags = selected_alert.get("behavioural_flags")
behaviour = selected_alert.get("behaviour")

if flags:
    st.write("**Behavioural Flags**")
    st.json(flags)
else:
    st.info("No behavioural flags recorded for this alert.")

if behaviour:
    st.write("**Behaviour Details**")
    st.json(behaviour)
else:
    st.info("No additional behaviour details recorded.")

# --------------------------------------------------
# TIMESTAMPS
# --------------------------------------------------

st.divider()
st.subheader("Processing Information")

st.write(
    "**Processed At:**",
    selected_alert.get("processed_at", "Not available"),
)

st.write(
    "**Replay Timestamp:**",
    selected_alert.get("replay_timestamp", "Not available"),
)

st.caption(
    "Fraud Alerts • Database: fraud_detection_demo • "
    "Maximum 100 alerts loaded"
)
